assert(not game:GetService("RunService"):IsRunning(),"Edit mode required");local rows=game.HttpService:JSONDecode([====[[{"path": ["StarterGui", "AnimalKingdomUI", "HatchPresentation"], "source": "local RS=game:GetService(\"ReplicatedStorage\")\nlocal Run=game:GetService(\"RunService\")\nlocal W=require(script.Parent.GameplayWidgets)\nlocal Resolver=require(RS.Shared.Gameplay.AssetResolver)\nlocal Appearance=require(RS.Shared.Gameplay.PetAppearance)\nlocal Pets=require(RS.Shared.Gameplay.Definitions.PetDefinitions)\nlocal Rarities=require(RS.Shared.Gameplay.Definitions.RarityDefinitions)\nlocal Sounds=require(RS.Shared.Gameplay.PresentationSounds)\nlocal Eggs=require(RS.Shared.Gameplay.Definitions.EggDefinitions)\nlocal H={Busy=false}\nlocal queue={}\nlocal activeClose\nfunction H.Play(screen,result,reduced)\n if H.Busy then table.insert(queue,{screen,result,reduced});return end;H.Busy=true\n local previousOrder=screen.DisplayOrder;screen.DisplayOrder=60\n local overlay=W.New(\"Frame\",{Name=\"HatchReveal\",Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.fromRGB(18,38,30),BackgroundTransparency=.12,ZIndex=100},screen)\n local title=W.Text(overlay,(Eggs[result.EggId] and Eggs[result.EggId].DisplayName or \"Biome Egg\")..\" \u00b7 A new friend is waiting\u2026\",UDim2.fromScale(.9,.1),UDim2.fromScale(.05,.07),26,Color3.new(1,1,1));title.TextXAlignment=Enum.TextXAlignment.Center\n local models,views={},{}\n for i,_ in ipairs(result.Results) do\n  local egg=Resolver.Create(\"Eggs\",Eggs[result.EggId] and Eggs[result.EggId].ModelName or result.EggId);local width=.9/#result.Results\n  local view=W.Viewport(overlay,egg,UDim2.fromScale(width,.55),UDim2.fromScale(.05+(i-1)*width,.2));views[i]=view;models[i]={Model=egg,Pivot=egg:GetPivot()}\n end\n Sounds.Play(\"EggWiggle\",screen)\n local connection;local started=os.clock();local duration=reduced and .15 or result.Duration\n local closed=false\n local function close()\n  if closed then return end;closed=true\n  if connection then connection:Disconnect() end\n  overlay:Destroy();H.Busy=false;activeClose=nil;screen.DisplayOrder=previousOrder\n  if #queue>0 then local nextHatch=table.remove(queue,1);task.defer(H.Play,table.unpack(nextHatch)) end\n end\n activeClose=close\n connection=Run.RenderStepped:Connect(function()\n  local elapsed=os.clock()-started\n  for _,entry in ipairs(models) do if entry.Model.Parent then entry.Model:PivotTo(entry.Pivot*CFrame.Angles(0,0,math.sin(elapsed*(18+18*math.min(1,elapsed/duration)))*.22*(elapsed/duration))) end end\n end)\n task.delay(duration,function()\n  if closed then return end\n  connection:Disconnect()\n  if not overlay.Parent then close();return end\n  Sounds.Play(\"EggCrack\",screen)\n  for _,view in ipairs(views) do view:Destroy() end\n  title.Text=\"Meet your new companion!\"\n  Sounds.Play(\"PetReveal\",screen)\n  local flash=W.New(\"Frame\",{Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=.15,BorderSizePixel=0,ZIndex=105},overlay)\n  game:GetService(\"TweenService\"):Create(flash,TweenInfo.new(.3),{BackgroundTransparency=1}):Play()\n  task.delay(.35,function() flash:Destroy() end)\n  for i,entry in ipairs(result.Results) do\n   local def=Pets[entry.Pet.PetId];local width=.9/#result.Results\n   local model=Appearance.Create(entry.Pet)\n   if model then W.Viewport(overlay,model,UDim2.fromScale(width,.5),UDim2.fromScale(.05+(i-1)*width,.18)) end\n   local label=W.Text(overlay,(def and def.DisplayName or entry.Pet.PetId)..\"\\n\"..(def and def.Rarity or \"\")..(entry.AutoDeleted and \"\\nAuto-deleted \u00b7 Index recorded\" or entry.NewDiscovery and \"\\nNew discovery!\" or \"\"),UDim2.fromScale(width,.18),UDim2.fromScale(.05+(i-1)*width,.64),17,def and Rarities[def.Rarity].Color or Color3.new(1,1,1));label.TextXAlignment=Enum.TextXAlignment.Center\n  end\n  W.Button(overlay,\"CONTINUE\",UDim2.fromScale(.5,.07),UDim2.fromScale(.25,.86),close)\n  task.delay(2.5,close)\n end)\nend\nfunction H.Cleanup() table.clear(queue);if activeClose then activeClose() end end\nreturn H\n"}, {"path": ["StarterGui", "AnimalKingdomUI", "Main"], "source": "local Players=game:GetService(\"Players\")\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal Collection=game:GetService(\"CollectionService\")\nlocal Knit=require(RS.Packages.Knit)\nlocal W=require(script.Parent.GameplayWidgets)\nlocal Bridge=require(script.Parent.RemoteBridge)\nlocal PetMenus=require(script.Parent.PetMenus)\nlocal ProgressionMenus=require(script.Parent.ProgressionMenus)\nlocal Hatch=require(script.Parent.HatchPresentation)\nlocal Tutorial=require(RS.Shared.Gameplay.Definitions.TutorialDefinitions)\nlocal screen=script.Parent;local player=Players.LocalPlayer\nscreen:SetAttribute(\"ProductionUI\",true);screen:SetAttribute(\"Version\",\"2.0.0\")\nlocal connections={};local function connect(signal,fn) local c=signal:Connect(fn);table.insert(connections,c);return c end\nlocal data,controller,active,dialog=nil,nil,nil,nil\nlocal ctx={Request=Bridge.Request};local refreshQueued=false\nlocal hud=W.New(\"Frame\",{Name=\"HUD\",Size=UDim2.fromScale(1,1),BackgroundTransparency=1},screen)\nlocal counters=W.New(\"Frame\",{Name=\"Currencies\",Size=UDim2.new(.55,0,0,64),Position=UDim2.fromOffset(12,8),BackgroundColor3=W.Color.Panel,BorderSizePixel=0},hud);W.Round(counters,16)\nW.New(\"UISizeConstraint\",{MinSize=Vector2.new(225,64),MaxSize=Vector2.new(410,64)},counters)\nlocal coins=W.Text(counters,\"Coins\\nLoading\u2026\",UDim2.new(.5,-12,1,0),UDim2.fromOffset(12,0),18)\nlocal tokens=W.Text(counters,\"Friendship Tokens\\nLoading\u2026\",UDim2.new(.5,-12,1,0),UDim2.fromScale(.5,0),15)\nlocal context=W.Text(hud,\"Meadow \u00b7 Clear skies\",UDim2.new(.55,0,0,24),UDim2.fromOffset(16,77),13,Color3.new(1,1,1));context.TextStrokeTransparency=.25\nlocal nav=W.New(\"Frame\",{Name=\"Navigation\",AnchorPoint=Vector2.new(.5,1),Position=UDim2.new(.5,0,1,-12),Size=UDim2.new(.96,0,0,52),BackgroundColor3=W.Color.Panel,BorderSizePixel=0},hud);W.Round(nav,14)\nW.New(\"UISizeConstraint\",{MaxSize=Vector2.new(800,52)},nav)\nlocal panel=W.New(\"Frame\",{Name=\"GameplayMenu\",AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.49),Size=UDim2.fromScale(.94,.75),BackgroundColor3=W.Color.Panel,BorderSizePixel=0,Visible=false,ZIndex=10},screen);W.Round(panel,18)\nW.New(\"UISizeConstraint\",{MaxSize=Vector2.new(800,740)},panel)\nlocal title=W.Text(panel,\"\",UDim2.new(1,-88,0,52),UDim2.fromOffset(18,6),24)\nlocal content=W.New(\"ScrollingFrame\",{Name=\"Content\",Position=UDim2.fromOffset(14,68),Size=UDim2.new(1,-28,1,-82),BackgroundTransparency=1,BorderSizePixel=0,AutomaticCanvasSize=Enum.AutomaticSize.Y,CanvasSize=UDim2.new(),ScrollBarThickness=5,ScrollingDirection=Enum.ScrollingDirection.Y},panel);ctx.Content=content\nlocal tutorial=W.New(\"Frame\",{Name=\"Tutorial\",AnchorPoint=Vector2.new(0,1),Position=UDim2.new(0,12,1,-78),Size=UDim2.new(.9,0,0,170),BackgroundColor3=W.Color.Panel,BorderSizePixel=0,Visible=false},hud);W.Round(tutorial,14)\nW.New(\"UISizeConstraint\",{MaxSize=Vector2.new(380,170)},tutorial)\nlocal tutorialTitle=W.Text(tutorial,\"\",UDim2.new(1,-24,0,28),UDim2.fromOffset(12,10),17)\nlocal tutorialBody=W.Text(tutorial,\"\",UDim2.new(1,-24,0,65),UDim2.fromOffset(12,42),14,W.Color.Muted)\nlocal nextButton=W.Button(tutorial,\"CONTINUE\",UDim2.new(1,-24,0,38),UDim2.fromOffset(12,118),function() Bridge.Request(\"TutorialNext\",{}) end)\nlocal marker=W.New(\"BillboardGui\",{Name=\"TutorialMarker\",Size=UDim2.fromOffset(180,46),StudsOffsetWorldSpace=Vector3.new(0,6,0),AlwaysOnTop=true,Enabled=false},screen)\nlocal markerText=W.Text(marker,\"\",UDim2.fromScale(1,1),nil,16,Color3.new(1,1,1));markerText.TextStrokeTransparency=.1\nfunction ctx.Close() active=nil;panel.Visible=false;screen.DisplayOrder=20;tutorial.Visible=data and not data.TutorialCompleted or false end\nW.Button(panel,\"\u00d7\",UDim2.fromOffset(42,42),UDim2.new(1,-54,0,12),ctx.Close,W.Color.Muted)\nlocal menus={Pets=PetMenus.Pets,Index=PetMenus.Index,Biomes=ProgressionMenus.Biomes,Challenges=ProgressionMenus.Challenges,Upgrades=ProgressionMenus.Upgrades,Settings=ProgressionMenus.Settings}\nlocal function render()\n if not data then return end\n ctx.Data=data\n coins.Text=\"Coins\\n\"..W.Format(data.Currencies.Coins or 0);tokens.Text=\"Friendship Tokens\\n\"..W.Format(data.Currencies.FriendshipTokens or 0)\n player:SetAttribute(\"AKReducedMotion\",data.Settings.ReducedMotion);player:SetAttribute(\"AKShowOtherPets\",data.Settings.ShowOtherPets)\n tutorial.Visible=not data.TutorialCompleted and active==nil\n local step=data.TutorialProgress.Step;local def=Tutorial[step]\n tutorialTitle.Text=step..\" / 14 \u00b7 \"..def.Title;tutorialBody.Text=def.Text\n nextButton.Visible=def.Continue==true\n if active then\n  local old=content.CanvasPosition;content:ClearAllChildren();title.Text=active\n  local menu=menus[active]\n  if not menu and active==\"Plot\" then menu=require(script.Parent.PlotMenu).Render end\n  if menu then menu(ctx) end\n  content.CanvasPosition=old\n end\nend\nfunction ctx.Refresh()\n if refreshQueued then return end;refreshQueued=true\n task.defer(function() refreshQueued=false;if screen.Parent then render() end end)\nend\nlocal tabs={\"Pets\",\"Index\",\"Biomes\",\"Challenges\",\"Upgrades\",\"Plot\",\"Settings\"}\nfor i,name in ipairs(tabs) do\n local button=W.Button(nav,name,UDim2.new(1/#tabs,-6,1,-12),UDim2.new((i-1)/#tabs,3,0,6),function()\n  if not data then return end\n  if active==name then ctx.Close() else active=name;panel.Visible=true;screen.DisplayOrder=40;content.CanvasPosition=Vector2.zero;ctx.Refresh() end\n end);button.TextSize=12\nend\nlocal notice=W.New(\"Frame\",{Name=\"Notifications\",AnchorPoint=Vector2.new(.5,0),Position=UDim2.fromScale(.5,.19),Size=UDim2.new(.85,0,0,48),BackgroundColor3=W.Color.Ink,BackgroundTransparency=.1,BorderSizePixel=0,Visible=false,ZIndex=80},screen);W.Round(notice)\nW.New(\"UISizeConstraint\",{MaxSize=Vector2.new(460,48)},notice)\nlocal noticeText=W.Text(notice,\"\",UDim2.new(1,-20,1,0),UDim2.fromOffset(10,0),16,Color3.new(1,1,1));noticeText.TextXAlignment=Enum.TextXAlignment.Center\nlocal queue,showing={},false\nlocal function advanceNotice()\n if #queue==0 then showing=false;notice.Visible=false;return end\n showing=true;notice.Visible=true;noticeText.Text=table.remove(queue,1)\n task.delay(2.2,function() if screen.Parent then advanceNotice() end end)\nend\nlocal function notify(text)\n if type(text)~=\"string\" or text==\"\" then return end\n if #queue<20 and queue[#queue]~=text then table.insert(queue,text) end\n if not showing then advanceNotice() end\nend\nctx.Notify=notify\nlocal function closeDialog() if dialog then dialog:Destroy();dialog=nil end end\nlocal function modal(text)\n closeDialog()\n dialog=W.New(\"Frame\",{Name=\"ActionDialog\",Size=UDim2.fromScale(.9,.35),Position=UDim2.fromScale(.5,.45),AnchorPoint=Vector2.new(.5,.5),BackgroundColor3=W.Color.Panel,BorderSizePixel=0,ZIndex=90},screen);W.Round(dialog,16)\n W.New(\"UISizeConstraint\",{MaxSize=Vector2.new(550,260),MinSize=Vector2.new(260,190)},dialog)\n W.Text(dialog,text,UDim2.new(1,-24,.55,-12),UDim2.fromOffset(12,10),18)\n W.Button(dialog,\"Cancel\",UDim2.new(1,-24,0,32),UDim2.new(0,12,1,-42),closeDialog,W.Color.Muted)\n return dialog\nend\n\nlocal remotes=RS:WaitForChild(\"AnimalKingdomRemotes\")\nconnect(remotes:WaitForChild(\"GameplayNotice\").OnClientEvent,function(payload) notify(payload.Message) end)\nconnect(remotes:WaitForChild(\"GameplayFeedback\").OnClientEvent,function(payload)\n local result=payload.Result\n if not payload.Success then notify(type(result)==\"string\" and result or \"Action unavailable\");return end\n if type(result)==\"string\" then notify(result)\n elseif type(result)==\"table\" and result.Kind==\"Hatch\" then ctx.Close();Hatch.Play(screen,result,data and data.Settings.ReducedMotion)\n elseif type(result)==\"table\" and result.Kind==\"DeleteConfirmation\" then\n  local root=modal(\"Delete this pet permanently?\\nThis cannot be undone.\")\n  W.Button(root,\"DELETE PET\",UDim2.new(1,-24,0,40),UDim2.new(0,12,.55,0),function() closeDialog();Bridge.Request(\"Delete\",{UID=result.UID,Token=result.Token}) end,W.Color.Red)\n end\nend)\nKnit.OnStart():andThen(function()\n controller=Knit.GetController(\"DataController\");data=controller:GetPlayerData()\n connect(controller.Changed,function(key,snapshot)\n  data=snapshot\n  local relevant={Pets={Pets=true,EquippedPets=true,PetStorageCapacity=true,MaxEquippedPets=true},Index={PetIndex=true,IndexRewards=true},Biomes={UnlockedBiomes=true},Upgrades={Upgrades=true},Challenges={DailyChallenges=true,WeeklyChallenges=true},Settings={Settings=true},Plot={PlotProgression=true,Items=true,UncollectedSanctuaryCoins=true}}\n  if not key or key==\"Currencies\" or key==\"Settings\" or key==\"TutorialProgress\" or key==\"TutorialCompleted\" or (active and relevant[active] and relevant[active][key]) then ctx.Refresh() end\n end)\n ctx.Refresh()\nend):catch(function(err) warn(\"[AnimalKingdomUI] \"..tostring(err)) end)\nlocal weather=RS:WaitForChild(\"WeatherState\")\nlocal function resizeHUD()\n local size=screen.AbsoluteSize\n local narrow=size.X<600\n local width=math.clamp(narrow and size.X-28 or size.X*.55,225,410)\n local y=8\n if narrow and weather:GetAttribute(\"Phase\")==\"Event\" then\n  if size.Y>380 then y=165 else width=math.max(225,size.X-255) end\n end\n counters.Size=UDim2.fromOffset(width,64);counters.Position=UDim2.fromOffset(12,y)\n context.Position=UDim2.fromOffset(16,y+69)\n local short=size.Y<420;local height=short and 126 or 170\n tutorial.Size=UDim2.new(.9,0,0,height)\n tutorialTitle.Position=UDim2.fromOffset(12,6);tutorialTitle.TextSize=short and 14 or 17\n tutorialBody.Position=UDim2.fromOffset(12,short and 30 or 42)\n tutorialBody.Size=UDim2.new(1,-24,0,short and 45 or 65);tutorialBody.TextSize=short and 12 or 14\n nextButton.Position=UDim2.fromOffset(12,height-46)\nend\nconnect(screen:GetPropertyChangedSignal(\"AbsoluteSize\"),resizeHUD)\nlocal function updateContext()\n local id=weather:GetAttribute(\"Phase\")==\"Event\" and weather:GetAttribute(\"EventId\") or \"Clear skies\"\n local def=require(RS.Shared.EventDefinitions)[id]\n resizeHUD()\n context.Text=(player:GetAttribute(\"CurrentBiome\") or \"Town\")..\" \u00b7 \"..(def and def.DisplayName or id)\nend\nconnect(weather.AttributeChanged,updateContext);connect(player:GetAttributeChangedSignal(\"CurrentBiome\"),updateContext);updateContext()\ntask.spawn(function()\n while screen.Parent do\n  task.wait(1)\n  marker.Enabled=false\n  if not data or data.TutorialCompleted or active then continue end\n  local step=Tutorial[data.TutorialProgress.Step];local root=player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n  if not step.Target or not root then continue end\n  local nearest,distance=nil,math.huge\n  for _,object in ipairs(Collection:GetTagged(\"GatherableTree\")) do\n   if object:IsDescendantOf(workspace) and object:GetAttribute(\"BiomeId\")==\"Meadow\" and (step.Target~=\"Tree\" or object:GetAttribute(\"ResourceState\")==\"AVAILABLE\") then\n    local part=object:FindFirstChild(\"AKTreeInteraction\",true) or (object:IsA(\"BasePart\") and object or object:FindFirstChildWhichIsA(\"BasePart\",true))\n    if part then local position=part:IsA(\"Attachment\") and part.WorldPosition or part.Position;local d=(position-root.Position).Magnitude;if d<distance then distance=d;nearest=part end end\n   end\n  end\n  if nearest then marker.Adornee=nearest;marker.Enabled=true;markerText.Text=step.Target..\" \u00b7 \"..math.floor(distance)..\" studs\" end\n end\nend)\nscript.Destroying:Connect(function() Hatch.Cleanup(); for _,c in ipairs(connections) do c:Disconnect() end end)\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "WorldContentService"], "source": "-- Bind existing authored trees only. Eggs exist exclusively in hatch presentation.\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal Collection=game:GetService(\"CollectionService\")\nlocal Knit=require(RS.Packages.Knit)\nlocal Resolver=require(RS.Shared.Gameplay.AssetResolver)\nlocal Discovery=require(script.Parent.Parent.Utilities.AuthoredTreeDiscovery)\nlocal Biomes=require(RS.Shared.Gameplay.Definitions.BiomeDefinitions)\nlocal World=Knit.CreateService({Name=\"WorldContentService\",Client={}})\nfunction World:RemoveGenerated()\n local removed=0\n for _,object in ipairs(workspace:GetDescendants()) do\n  local category=object:GetAttribute(\"AssetCategory\")\n  -- The previous generator stamped all its output. Never delete by tree-like names.\n  if object:GetAttribute(\"GameplayGenerated\")==true and (category==\"Trees\" or category==\"Resources\" or category==\"Eggs\") then\n   object:Destroy();removed+=1\n  end\n end\n local runtime=workspace:FindFirstChild(\"AKGameplayRuntime\")\n if runtime and #runtime:GetChildren()==0 then runtime:Destroy() end\n -- Retire legacy world egg interactions, preserving any unmarked authored geometry.\n for _,object in ipairs(Collection:GetTagged(\"EggStation\")) do\n  Collection:RemoveTag(object,\"EggStation\")\n  for _,child in ipairs(object:GetDescendants()) do if child:IsA(\"ProximityPrompt\") and child.Name==\"EggPrompt\" then child:Destroy() end end\n end\n return removed\nend\nfunction World:RegisterAuthoredTrees()\n local counts={};for _,biome in ipairs(Biomes.Ordered) do counts[biome.Id]=0 end\n for _,entry in ipairs(Discovery.Scan()) do\n  local object=entry.Object\n  object:SetAttribute(\"BiomeId\",entry.Biome);object:SetAttribute(\"ResourceType\",\"Tree\")\n  object:SetAttribute(\"AuthoredGatherableTree\",true);object:SetAttribute(\"RespawnTime\",20)\n  object:SetAttribute(\"InteractionPosition\",entry.InteractionPosition)\n  object:SetAttribute(\"EggId\",Biomes[entry.Biome].EggId)\n  Collection:AddTag(object,\"GatherableTree\");counts[entry.Biome]+=1\n end\n self.Counts=counts\n for _,biome in ipairs(Biomes.Ordered) do\n  print(\"[AuthoredTrees] \"..biome.Id..\": \"..counts[biome.Id])\n  if counts[biome.Id]==0 then warn(\"[AuthoredTrees] No confirmed authored trees found in \"..biome.Id..\"; no replacements generated\") end\n end\n return counts\nend\nfunction World:KnitInit() Resolver.EnsureFolders() end\nfunction World:KnitStart() self:RemoveGenerated();self:RegisterAuthoredTrees() end\nreturn World\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "EggService"], "source": "local RS=game:GetService(\"ReplicatedStorage\")\nlocal Knit=require(RS.Packages.Knit)\nlocal Signal=require(RS.Packages.Signal)\nlocal Eggs=require(RS.Shared.Gameplay.Definitions.EggDefinitions)\nlocal BiomeDefinitions=require(RS.Shared.Gameplay.Definitions.BiomeDefinitions)\nlocal Definitions=require(RS.Shared.Gameplay.Definitions.PetDefinitions)\nlocal Variants=require(RS.Shared.Gameplay.Definitions.VariantDefinitions)\nlocal PetMath=require(RS.Shared.Gameplay.PetMath)\nlocal Guard=require(script.Parent.Parent.Utilities.GameplayGuard)\nlocal Egg=Knit.CreateService({Name=\"EggService\",Client={},Hatched=Signal.new()})\nlocal lastHatch=setmetatable({},{__mode=\"k\"});local rng=Random.new()\nlocal Data,Biomes,Pets,Modifiers,Loot\n-- Called only by server resource flow. No client-supplied egg ID, pet ID or price.\nfunction Egg:CheckTreeHatch(player,tree)\n local record=Knit.GetService(\"ResourceService\"):GetRecords()[tree]\n local biome=record and record.IsTree and BiomeDefinitions[record.Biome]\n local id=biome and biome.EggId;local def=id and Eggs[id]\n if not def or def.Biome~=record.Biome or not tree:IsDescendantOf(workspace) then return false,\"Invalid tree egg\" end\n local data=Data:Get(player);local root=Guard.Alive(player)\n if not data or not root or (root.Position-record.InteractionPosition).Magnitude>18 then return false,\"Move closer to the tree\" end\n if not Biomes:IsUnlocked(player,record.Biome) then return false,\"Biome locked\" end\n if def.Season and not Knit.GetService(\"SeasonalService\"):IsActive(def.Season) then return false,\"Season is inactive\" end\n if not Pets:HasSpace(player,1) then return false,\"PET INVENTORY FULL\" end\n if lastHatch[player] and os.clock()<lastHatch[player] then return false,\"Hatch in progress\" end\n return true,def,id,data\nend\nlocal function roll(player,def,data,count)\n local results={}\n -- Shared weighted RNG and existing variant modifiers remain server-owned.\n for _=1,count do\n  local selection=Loot:Roll(def.Pets,function(entry) return Modifiers:GetPetWeight(player,Definitions[entry.PetId],entry.Weight,def.Biome) end)\n  if not selection then return false,\"Egg is unavailable\" end\n  local mutationPool={}\n  for mutation,v in pairs(Variants.Mutations) do\n   local weight=v.Weight\n   if mutation==\"Spirit\" and Knit.GetService(\"WeatherGameplayService\"):GetEventId()==\"SpiritNight\" then weight=150 end\n   table.insert(mutationPool,{Id=mutation,Weight=weight*(mutation==\"Normal\" and 1 or Modifiers:Get(player,\"MutationChance\",def.Biome))})\n  end\n  table.sort(mutationPool,function(a,b) return a.Id<b.Id end)\n  local mutation=Loot:Roll(mutationPool).Id\n  local shiny=rng:NextNumber()<math.min(.5,Variants.ShinyChance*Modifiers:Get(player,\"Shiny\",def.Biome))\n  local prismatic=rng:NextNumber()<math.min(.05,Variants.PrismaticChance*Modifiers:Get(player,\"Luck\",def.Biome))\n  local pet=Pets:Create(selection.PetId,mutation,shiny,prismatic)\n  if not pet then return false,\"Pet definition unavailable\" end\n  table.insert(results,{Pet=pet,AutoDeleted=data.Settings.AutoDelete[Definitions[pet.PetId].Rarity]==true and not PetMath.Protected(pet)})\n end\n return true,results\nend\nfunction Egg:HatchFromTree(player,tree,claim)\n local record=Knit.GetService(\"ResourceService\"):GetRecords()[tree]\n if not record or record.State~=\"SHAKING\" or record.Player~=player or record.Claim~=claim or not claim or record.Awarded then return false,\"Tree claim unavailable\" end\n local valid,def,id,data=self:CheckTreeHatch(player,tree)\n if not valid then return false,def end\n local ok,results=roll(player,def,data,1)\n if not ok then return false,results end\n -- No yielding code separates the final capacity check and the saved inventory commit.\n for _,result in ipairs(results) do\n  result.NewDiscovery=Pets:Discover(data,result.Pet)\n  if not result.AutoDeleted then table.insert(data.Pets,result.Pet) end\n end\n local duration=math.max(.6,def.HatchSeconds/Modifiers:Get(player,\"HatchSpeed\"))\n record.HatchResult={Kind=\"Hatch\",Source=\"Tree\",EggId=id,Results=results,Duration=duration}\n record.Awarded=true\n lastHatch[player]=os.clock()+duration+1.5 -- allow reveal, also bounds presentation queue growth\n Pets:Publish(player)\n for _,result in ipairs(results) do Pets.Granted:Fire(player,result.Pet,result.NewDiscovery) end\n self.Hatched:Fire(player,1,record.Biome)\n return true,record.HatchResult\nend\n-- Retired compatibility entry: arbitrary world egg requests cannot produce a reward.\nfunction Egg:Hatch() return false,\"Shake a biome tree to hatch an egg\" end\nfunction Egg:KnitInit()\n Data=Knit.GetService(\"PlayerDataService\");Biomes=Knit.GetService(\"BiomeService\")\n Pets=Knit.GetService(\"PetService\");Modifiers=Knit.GetService(\"ModifierService\");Loot=Knit.GetService(\"LootService\")\nend\nreturn Egg\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "ResourceService"], "source": "local RS=game:GetService(\"ReplicatedStorage\")\nlocal Collection=game:GetService(\"CollectionService\")\nlocal RunService=game:GetService(\"RunService\")\nlocal Knit=require(RS.Packages.Knit)\nlocal Signal=require(RS.Packages.Signal)\nlocal Guard=require(script.Parent.Parent.Utilities.GameplayGuard)\nlocal Tables=require(RS.Shared.Gameplay.Definitions.DropTables)\nlocal Resource=Knit.CreateService({Name=\"ResourceService\",Client={},Harvested=Signal.new()})\nlocal records,shaking={},{}\nlocal busy=setmetatable({},{__mode=\"k\"})\nlocal Data,Biomes,Loot,Modifiers,Pets,Egg\nlocal function move(object,cf) object:PivotTo(cf) end\nlocal function hide(record)\n for object,properties in pairs(record.Properties) do\n  if object.Parent then\n   if object:IsA(\"BasePart\") then object.Transparency=1;object.CanCollide=false;object.CanTouch=false;object.CanQuery=false\n   elseif object:IsA(\"Decal\") or object:IsA(\"Texture\") then object.Transparency=1\n   elseif properties.Enabled~=nil then\n    object.Enabled=false\n    if object:IsA(\"ParticleEmitter\") or object:IsA(\"Trail\") then object:Clear() end\n   end\n  end\n end\nend\nlocal function resetPose(record)\n move(record.Object,record.Pivot)\n -- MeshPart/PrimaryPart pivot offsets can round a PivotTo round-trip. Restoring\n -- saved part frames also prevents cumulative drift in nested imported assets.\n for part,properties in pairs(record.Properties) do if properties.CFrame and part.Parent then part.CFrame=properties.CFrame end end\nend\nlocal function restore(record)\n if not record.Object:IsDescendantOf(workspace) then return end\n resetPose(record)\n for object,properties in pairs(record.Properties) do if object.Parent then for key,value in pairs(properties) do object[key]=value end end end\n record.State=\"AVAILABLE\";record.Claim=nil;record.Awarded=nil;record.HatchResult=nil\n record.Object:SetAttribute(\"ResourceState\",\"AVAILABLE\");record.Object:SetAttribute(\"RespawnAt\",nil)\nend\nlocal function notify(player,message)\n if Guard.IsPlayer(player) then Knit.GetService(\"NotificationService\"):Send(player,message,\"Error\") end\nend\nfunction Resource:Register(object)\n if records[object] or object:GetAttribute(\"GameplayGenerated\")==true or not object:IsDescendantOf(workspace) or not (object:IsA(\"Model\") or object:IsA(\"BasePart\")) then return end\n local isTree=Collection:HasTag(object,\"GatherableTree\")\n if isTree and object:GetAttribute(\"AuthoredGatherableTree\")~=true then return end\n local biome=object:GetAttribute(\"BiomeId\");local tableId=object:GetAttribute(\"DropTable\") or (type(biome)==\"string\" and biome..\"Tree\")\n if not Tables[tableId] then warn(\"[ResourceService] Missing biome/drop table: \"..object:GetFullName());return end\n local root=object:IsA(\"BasePart\") and object or object.PrimaryPart or object:FindFirstChildWhichIsA(\"BasePart\",true)\n if not root then return end\n local original=object:GetPivot()\n local interaction=object:GetAttribute(\"InteractionPosition\")\n if typeof(interaction)~=\"Vector3\" then interaction=original.Position end\n local anchor=root:FindFirstChild(\"AKTreeInteraction\")\n if not anchor then anchor=Instance.new(\"Attachment\");anchor.Name=\"AKTreeInteraction\";anchor.Parent=root end\n anchor.WorldPosition=interaction\n local prompt=anchor:FindFirstChild(\"GatherPrompt\") or Instance.new(\"ProximityPrompt\")\n prompt.Name=\"GatherPrompt\";prompt.ActionText=isTree and \"SHAKE TREE\" or \"GATHER\";prompt.ObjectText=isTree and \"Tree\" or \"Resource\"\n prompt.HoldDuration=.2;prompt.MaxActivationDistance=14;prompt.RequiresLineOfSight=false;prompt.Parent=anchor\n local record={Object=object,Pivot=original,InteractionPosition=interaction,IsTree=isTree,State=\"AVAILABLE\",Properties={},Prompt=prompt,Biome=biome,Table=tableId}\n local objects=object:GetDescendants();table.insert(objects,object)\n for _,v in ipairs(objects) do\n  if v:IsA(\"BasePart\") then record.Properties[v]={CFrame=v.CFrame,Transparency=v.Transparency,CanCollide=v.CanCollide,CanTouch=v.CanTouch,CanQuery=v.CanQuery}\n  elseif v:IsA(\"Decal\") or v:IsA(\"Texture\") then record.Properties[v]={Transparency=v.Transparency}\n  elseif v:IsA(\"ProximityPrompt\") or v:IsA(\"BillboardGui\") or v:IsA(\"SurfaceGui\") or v:IsA(\"ParticleEmitter\") or v:IsA(\"Trail\") or v:IsA(\"Beam\") or v:IsA(\"Light\") or v:IsA(\"Highlight\") or v:IsA(\"Smoke\") or v:IsA(\"Fire\") or v:IsA(\"Sparkles\") then record.Properties[v]={Enabled=v.Enabled} end\n end\n records[object]=record;object:SetAttribute(\"ResourceState\",\"AVAILABLE\");object:SetAttribute(\"RespawnTime\",20)\n record.Connection=prompt.Triggered:Connect(function(player) local ok,message=self:Gather(player,object);if not ok then notify(player,message) end end)\nend\nfunction Resource:Gather(player,object)\n if not Guard.RateLimit(player,\"Resource\",.3) then return false,\"Please wait\" end\n local record=records[object];local root=Guard.Alive(player)\n if not record or record.State~=\"AVAILABLE\" or busy[player] or not Data:Get(player) or not root or (root.Position-record.InteractionPosition).Magnitude>18 then return false,\"Tree unavailable\" end\n if not Biomes:IsUnlocked(player,record.Biome) then return false,\"Biome locked\" end\n local season=object:GetAttribute(\"Season\")\n if season and not Knit.GetService(\"SeasonalService\"):IsActive(season) then return false,\"Season is inactive\" end\n if record.IsTree then local ok,message=Egg:CheckTreeHatch(player,object);if not ok then return false,message end end\n -- Atomic claim and per-player guard happen before animation can yield.\n record.State=\"SHAKING\";record.Player=player;record.Started=os.clock();record.Claim={};record.Awarded=nil;record.HatchResult=nil\n record.Prompt.Enabled=false;busy[player]=record\n object:SetAttribute(\"ResourceState\",\"SHAKING\");shaking[object]=record\n local remotes=RS:FindFirstChild(\"AnimalKingdomRemotes\")\n if remotes and remotes:FindFirstChild(\"GatherVisual\") then remotes.GatherVisual:FireAllClients(player.UserId,record.InteractionPosition,1.2,object) end\n return true\nend\nfunction Resource:Finish(record)\n local object,player=record.Object,record.Player\n if records[object]~=record or record.State~=\"SHAKING\" or not player then return end\n shaking[object]=nil\n if not object:IsDescendantOf(workspace) then busy[player]=nil;record.Player=nil;return end\n resetPose(record)\n local success,result\n if record.IsTree then\n  local ok,accepted,response=pcall(Egg.HatchFromTree,Egg,player,object,record.Claim)\n  success=ok and accepted or record.Awarded==true;result=record.HatchResult or response\n  if not ok then warn(\"[ResourceService] Tree hatch: \"..tostring(accepted)) end\n else\n  local root=Guard.Alive(player)\n  success=Data:Get(player) and root and (root.Position-record.InteractionPosition).Magnitude<=18 and Biomes:IsUnlocked(player,record.Biome)\n end\n busy[player]=nil;record.Player=nil\n if not success then restore(record);notify(player,type(result)==\"string\" and result or \"Tree hatch cancelled; try again\");return end\n -- Commit is final. Hide this same instance before requesting presentation.\n record.State=\"RESPAWNING\";object:SetAttribute(\"ResourceState\",\"RESPAWNING\");hide(record)\n record.ReturnAt=workspace:GetServerTimeNow()+20;object:SetAttribute(\"RespawnAt\",record.ReturnAt)\n task.delay(20,function() if records[object]==record then restore(record) end end)\n if record.IsTree then\n  local remotes=RS:FindFirstChild(\"AnimalKingdomRemotes\")\n  if remotes and remotes:FindFirstChild(\"GameplayFeedback\") and Guard.IsPlayer(player) then remotes.GameplayFeedback:FireClient(player,{Action=\"TreeHatch\",Success=true,Result=result}) end\n end\n -- Secondary economy/XP drops preserve existing progression; an egg is the primary reward.\n local ok,err=pcall(function()\n  local power=Pets:GetGatheringPower(player)\n  local multiplier=Modifiers:Get(player,\"ResourceRewards\",record.Biome)*(1+math.min(power,5000)/50)\n  Loot:Reward(player,record.Table,multiplier,\"Gather\")\n  local weather=Knit.GetService(\"WeatherGameplayService\"):GetEventId()\n  if weather==\"MeteorShower\" then Loot:Reward(player,\"MeteorLoot\",1,\"Weather\")\n  elseif weather==\"Thunderstorm\" then Loot:Reward(player,\"StormLoot\",1,\"Weather\") end\n  Pets:AddEquippedXP(player,10)\n end)\n if not ok then warn(\"[ResourceService] Secondary reward failed: \"..tostring(err)) end\n if record.IsTree and Data:Get(player) then self.Harvested:Fire(player,record.Biome,#Data:Get(player).EquippedPets>0) end\nend\nfunction Resource:GetRecords() return records end\nfunction Resource:KnitInit()\n Data=Knit.GetService(\"PlayerDataService\");Biomes=Knit.GetService(\"BiomeService\");Loot=Knit.GetService(\"LootService\")\n Modifiers=Knit.GetService(\"ModifierService\");Pets=Knit.GetService(\"PetService\");Egg=Knit.GetService(\"EggService\")\nend\nfunction Resource:KnitStart()\n for _,tag in ipairs({\"GatherableTree\",\"GatherableResource\"}) do\n  Collection:GetInstanceAddedSignal(tag):Connect(function(object) self:Register(object) end)\n  Collection:GetInstanceRemovedSignal(tag):Connect(function(object)\n   local r=records[object];if not r then return end\n   if object:IsDescendantOf(workspace) and (Collection:HasTag(object,\"GatherableTree\") or Collection:HasTag(object,\"GatherableResource\")) then return end\n   r.Connection:Disconnect();if r.Player then busy[r.Player]=nil end;r.Player=nil;shaking[object]=nil;records[object]=nil\n   if object.Parent then restore(r) end\n  end)\n  for _,object in ipairs(Collection:GetTagged(tag)) do self:Register(object) end\n end\n RunService.Heartbeat:Connect(function()\n  local now=os.clock()\n  for object,record in pairs(shaking) do\n   if not object:IsDescendantOf(workspace) then shaking[object]=nil;if record.Player then busy[record.Player]=nil;record.Player=nil end\n   else\n    local elapsed=now-record.Started\n    if elapsed>=1.2 then self:Finish(record)\n    else move(object,record.Pivot*CFrame.Angles(0,0,math.sin(elapsed*30)*.035*(1-elapsed/1.2))) end\n   end\n  end\n end)\nend\nreturn Resource\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "GameplayService"], "source": "local RS=game:GetService(\"ReplicatedStorage\")\nlocal Players=game:GetService(\"Players\")\nlocal Knit=require(RS.Packages.Knit)\nlocal Policy=require(script.Parent.Parent.Utilities.GameplayRequestPolicy)\nlocal Rarities=require(RS.Shared.Gameplay.Definitions.RarityDefinitions)\nlocal Service=Knit.CreateService({Name=\"GameplayService\",Client={}})\nlocal Data;local busy=setmetatable({},{__mode=\"k\"})\nlocal function remote(folder,name)\n local r=folder:FindFirstChild(name)\n if r then assert(r:IsA(\"RemoteEvent\"),name..\" must be a RemoteEvent\");return r end\n r=Instance.new(\"RemoteEvent\");r.Name=name;r.Parent=folder;return r\nend\nfunction Service:Dispatch(player,action,p)\n local pets=Knit.GetService(\"PetService\")\n if action==\"Equip\" then return pets:Equip(player,p.UID,p.Equipped)\n elseif action==\"Favorite\" then return pets:Flag(player,p.UID,\"Favorite\",p.Value)\n elseif action==\"Lock\" then return pets:Flag(player,p.UID,\"Locked\",p.Value)\n elseif action==\"RequestDelete\" then return pets:RequestDelete(player,p.UID)\n elseif action==\"Delete\" then return pets:Delete(player,p.UID,p.Token)\n elseif action==\"Gather\" then return Knit.GetService(\"ResourceService\"):Gather(player,p.Target)\n elseif action==\"Upgrade\" then return Knit.GetService(\"UpgradeService\"):Purchase(player,p.Id)\n elseif action==\"UnlockBiome\" then return Knit.GetService(\"BiomeService\"):Unlock(player,p.Id)\n elseif action==\"ClaimChallenge\" then return Knit.GetService(\"ChallengeService\"):Claim(player,p.Period,p.Id)\n elseif action==\"ClaimIndex\" then return Knit.GetService(\"IndexService\"):Claim(player,p.Percent)\n elseif action==\"ClaimSeasonal\" then return Knit.GetService(\"SeasonalService\"):Claim(player,p.Season,p.RewardId)\n elseif action==\"TutorialNext\" then return Knit.GetService(\"TutorialService\"):Advance(player)\n elseif action==\"ShopBuy\" then return Knit.GetService(\"ShopService\"):Buy(player,p.Id)\n elseif action==\"Place\" then return Knit.GetService(\"PlacementService\"):Place(player,p.Id,p.Offset,p.Rotation)\n elseif action==\"RemovePlacement\" then return Knit.GetService(\"PlacementService\"):Remove(player,p.UID)\n elseif action==\"PlotVisitors\" then return Knit.GetService(\"PlotService\"):SetVisitors(player,p.Allowed)\n elseif action==\"PlotUpgrade\" then return Knit.GetService(\"PlotService\"):Upgrade(player)\n elseif action==\"CollectIdle\" then return Knit.GetService(\"PlotService\"):Collect(player)\n elseif action==\"Setting\" or action==\"AutoDelete\" then\n  local data=Data:Get(player)\n  if action==\"AutoDelete\" then\n   if not Rarities[p.Rarity] or p.Rarity==\"Secret\" then return false,\"Protected rarity\" end\n   data.Settings.AutoDelete[p.Rarity]=p.Value\n  else\n   if p.Id~=\"ReducedMotion\" and p.Id~=\"ShowOtherPets\" then return false,\"Invalid setting\" end\n   data.Settings[p.Id]=p.Value\n  end\n  Data:Publish(player,\"Settings\");return true\n end\n return false,\"Invalid action\"\nend\nfunction Service:KnitInit()\n Data=Knit.GetService(\"PlayerDataService\")\n local folder=RS:FindFirstChild(\"AnimalKingdomRemotes\") or Instance.new(\"Folder\");folder.Name=\"AnimalKingdomRemotes\";folder.Parent=RS\n self.Request=remote(folder,\"UIRequest\");self.Feedback=remote(folder,\"GameplayFeedback\")\n remote(folder,\"GameplayNotice\");remote(folder,\"GatherVisual\")\nend\nfunction Service:KnitStart()\n self.Request.OnServerEvent:Connect(function(player,action,payload,...)\n  if select(\"#\",...)~=0 or not Policy.Check(player,action,payload) or busy[player] or not Data:Get(player) then return end\n  busy[player]=true\n  local ok,success,result=pcall(self.Dispatch,self,player,action,payload)\n  busy[player]=nil\n  if not ok then warn(\"[GameplayService] \"..tostring(action)..\": \"..tostring(success));success=false;result=\"Action unavailable; please try again\" end\n  if player.Parent==Players then self.Feedback:FireClient(player,{Action=action,Success=success==true,Result=result}) end\n end)\nend\nreturn Service\n"}, {"path": ["ServerScriptService", "ServerSource", "Utilities", "GameplayRequestPolicy"], "source": "local Guard=require(script.Parent.GameplayGuard)\nlocal Policy={}\nlocal id=Guard.Id\nlocal boolean=function(v) return type(v)==\"boolean\" end\nlocal number=function(v) return Guard.Finite(v) and v>=0 and v%1==0 and v<=1e7 end\nlocal target=function(v) return typeof(v)==\"Instance\" and (v:IsA(\"Model\") or v:IsA(\"BasePart\")) and v:IsDescendantOf(workspace) end\nlocal offset=function(v) return typeof(v)==\"Vector3\" and Guard.Finite(v.X) and Guard.Finite(v.Y) and Guard.Finite(v.Z) and v.Magnitude<1000 end\nPolicy.Actions={\n Equip={.15,{UID=id,Equipped=boolean}},Favorite={.15,{UID=id,Value=boolean}},Lock={.15,{UID=id,Value=boolean}},\n RequestDelete={.3,{UID=id}},Delete={.3,{UID=id,Token=id}},\n Gather={.3,{Target=target}},Upgrade={.4,{Id=id}},UnlockBiome={.5,{Id=id}},ClaimChallenge={.4,{Period=function(v) return v==\"Daily\" or v==\"Weekly\" end,Id=id}},\n ClaimIndex={.5,{Percent=number}},ClaimSeasonal={.5,{Season=id,RewardId=id}},Setting={.2,{Id=id,Value=boolean}},AutoDelete={.2,{Rarity=id,Value=boolean}},\n TutorialNext={.3,{}},ShopBuy={.5,{Id=id}},Place={.4,{Id=id,Offset=offset,Rotation=number}},RemovePlacement={.4,{UID=id}},\n PlotVisitors={.5,{Allowed=boolean}},PlotUpgrade={.5,{}},CollectIdle={.5,{}},\n}\nfunction Policy.Check(player,action,payload)\n if not Guard.IsPlayer(player) or not Guard.RateLimit(player,\"GameplayGlobal\",.08) then return false end\n if type(action)~=\"string\" or #action>32 then return false end\n local spec=Policy.Actions[action]\n if not spec or not Guard.Shape(payload,spec[2]) or not Guard.RateLimit(player,\"Gameplay:\"..action,spec[1]) then return false end\n return Guard.Alive(player)~=nil\nend\nreturn Policy\n"}, {"path": ["ServerScriptService", "ServerSource", "Utilities", "AuthoredTreeDiscovery"], "source": "-- Read-only discovery: never renames, reparents, clones or replaces authored geometry.\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal Landing=require(game:GetService(\"ServerScriptService\").BiomeTeleport.Landing)\nlocal Biomes=require(RS.Shared.Gameplay.Definitions.BiomeDefinitions)\nlocal Assets=require(RS.Shared.Gameplay.Definitions.AuthoredTreeDefinitions)\nlocal Discovery={}\nfunction Discovery.IsTree(object)\n if not (object:IsA(\"Model\") or object:IsA(\"BasePart\")) or object:GetAttribute(\"GameplayGenerated\")==true then return false end\n local source=object:GetAttribute(\"SourceAssetName\") or object:GetAttribute(\"TreeType\")\n if source then return Assets[source]==true end\n -- These specific authored families have no source metadata; inspected as whole trees.\n local name=object.Name\n return name:match(\"^MagicalForestTree_%d+_AK_MagicTree$\")~=nil\n  or name:match(\"^MagicalForestTree_%d+_AK_LowpolyWillow$\")~=nil\n  or name:match(\"^MagicalForestTree_%d+_AK_NimbusWillow$\")~=nil\n  or name:match(\"^AncientRuinsTree_%d+_Type[123]$\")~=nil\n  or name==\"AK_AncientRuins_CypressTree\" or name==\"AK_AncientRuins_StylizedTree\"\n  or (object.Parent==workspace and name:match(\"^DecorTree[1-6]$\")~=nil)\n  or (object.Parent and object.Parent.Name==\"Volcano island lowpoly\" and (name==\"Palm tree_1\" or name==\"Palm tree_2\"))\nend\nfunction Discovery.Scan()\n local floors={}\n for _,def in ipairs(Biomes.Ordered) do local floor=Landing.FindFloor(def.Id);if floor then table.insert(floors,{Id=def.Id,Part=floor}) end end\n local found={}\n for _,object in ipairs(workspace:GetDescendants()) do\n  if not Discovery.IsTree(object) then continue end\n  local nested=false;local parent=object.Parent\n  while parent and parent~=workspace do\n   if Discovery.IsTree(parent) or parent:GetAttribute(\"GameplayGenerated\")==true then nested=true;break end\n   parent=parent.Parent\n  end\n  if nested then continue end\n  local root=object:IsA(\"BasePart\") and object or object.PrimaryPart or object:FindFirstChildWhichIsA(\"BasePart\",true)\n  if not root then continue end\n  local pivot=object:GetPivot()\n  local bounds,size;if object:IsA(\"Model\") then bounds,size=object:GetBoundingBox() else bounds,size=object.CFrame,object.Size end\n  local halfHeight=(math.abs(bounds.RightVector.Y)*size.X+math.abs(bounds.UpVector.Y)*size.Y+math.abs(bounds.LookVector.Y)*size.Z)/2\n  local bottom=bounds.Position.Y-halfHeight\n  local hint=object:GetAttribute(\"Biome\") or object:GetAttribute(\"BiomeName\")\n  local selected;local score=math.huge\n  for _,floor in ipairs(floors) do\n   local point=floor.Part.CFrame:PointToObjectSpace(Vector3.new(pivot.Position.X,bottom,pivot.Position.Z))\n   local vertical=math.abs(point.Y-floor.Part.Size.Y/2)\n   if math.abs(point.X)<=floor.Part.Size.X/2 and math.abs(point.Z)<=floor.Part.Size.Z/2 and vertical<=30 then\n    local priority=vertical+(hint==floor.Id and -100 or 0)\n    if priority<score then selected=floor;score=priority end\n   end\n  end\n  if not selected then continue end -- Town/admin/set dressing outside real biome floors stays inert.\n  local anchored=true\n  local parts=object:GetDescendants();if object:IsA(\"BasePart\") then table.insert(parts,object) end\n  for _,part in ipairs(parts) do if part:IsA(\"BasePart\") and not part.Anchored then anchored=false;break end end\n  if not anchored then warn(\"[TreeDiscovery] Unanchored authored tree skipped: \"..object:GetFullName());continue end\n  -- Prompt stays at reachable trunk height even if PrimaryPart is a canopy mesh.\n  local floorTop=selected.Part.Position.Y+selected.Part.Size.Y/2\n  local interaction=Vector3.new(pivot.Position.X,math.max(bottom,floorTop)+3,pivot.Position.Z)\n  table.insert(found,{Object=object,Biome=selected.Id,Root=root,Pivot=pivot,InteractionPosition=interaction})\n end\n return found\nend\nreturn Discovery\n"}, {"path": ["ReplicatedStorage", "Shared", "Gameplay", "PresentationSounds"], "source": "local Definitions=require(script.Parent.Definitions.GameplayEffectsDefinitions)\nlocal Debris=game:GetService(\"Debris\")\nlocal Sounds={}\nfunction Sounds.Play(id,parent)\n local def=Definitions[id]\n if not def or def.SoundId==\"\" then return end\n local sound=Instance.new(\"Sound\");sound.Name=id; sound.SoundId=def.SoundId;sound.Volume=def.Volume\n sound.RollOffMaxDistance=55;sound.Parent=parent;sound:Play();Debris:AddItem(sound,8)\nend\nreturn Sounds\n"}, {"path": ["ReplicatedStorage", "Shared", "Gameplay", "Definitions", "EggDefinitions"], "source": "local Biomes=require(script.Parent.BiomeDefinitions)\nlocal Pets=require(script.Parent.PetDefinitions)\nlocal weights={Common=55,Uncommon=28,Rare=12,Epic=4,Legendary=.9,Mythical=.1,Secret=.001}\nlocal eggs={}\nfor _,biome in ipairs(Biomes.Ordered) do\n local pool={}\n for _,pet in ipairs(Pets.Ordered) do\n  if pet.Biome==biome.Id then table.insert(pool,{PetId=pet.PetId,Weight=weights[pet.Rarity]}) end\n end\n eggs[biome.EggId]={Id=biome.EggId,DisplayName=biome.DisplayName..\" Egg\",ModelName=biome.EggId,Currency=\"Coins\",\n  Cost=biome.Order==1 and 250 or math.max(750,math.floor(biome.Cost/10)),Biome=biome.Id,Pets=pool,AllowTriple=true,HatchSeconds=2}\nend\n-- Named introductory pets coexist with the preserved 300-pet collection.\neggs.MeadowEgg.Pets={{PetId=\"Bunny\",Weight=55},{PetId=\"Dog\",Weight=30},{PetId=\"Deer\",Weight=12},{PetId=\"GoldenFox\",Weight=3}}\n-- The legacy Meadow collection remains obtainable from its collection egg.\neggs.MeadowCollectionEgg={Id=\"MeadowCollectionEgg\",DisplayName=\"Meadow Collection Egg\",ModelName=\"MeadowCollectionEgg\",Currency=\"Coins\",Cost=500,Biome=\"Meadow\",Pets={},AllowTriple=true,HatchSeconds=2}\nfor _,pet in ipairs(Pets.Ordered) do if pet.Biome==\"Meadow\" and pet.PetId:match(\"^Meadow_\") then table.insert(eggs.MeadowCollectionEgg.Pets,{PetId=pet.PetId,Weight=weights[pet.Rarity]}) end end\n-- Preserve access to legacy Meadow Index entries after retiring its separate world stand.\n-- Introductory pets retain 80% total weight; the legacy collection shares the remaining 20%.\nlocal total=0;for _,entry in ipairs(eggs.MeadowCollectionEgg.Pets) do total+=entry.Weight end\nfor _,entry in ipairs(eggs.MeadowCollectionEgg.Pets) do table.insert(eggs.MeadowEgg.Pets,{PetId=entry.PetId,Weight=entry.Weight/total*25}) end\nreturn eggs\n"}, {"path": ["ReplicatedStorage", "Shared", "Gameplay", "Definitions", "TutorialDefinitions"], "source": "return {\n {Title=\"Welcome to Animal Kingdom\",Text=\"Build your collection, grow stronger, and explore twelve biomes.\",Continue=true},\n {Title=\"Your own plot\",Text=\"Your username marks your plot. It belongs to you for this server session.\",Continue=true},\n {Title=\"Find your first tree\",Text=\"Travel to Meadow from Biomes, then follow the tree marker and use Shake.\",Target=\"Tree\"},\n {Title=\"A successful shake\",Text=\"Your tree hatched a biome egg! Each tree rewards one player at a time.\",Continue=true},\n {Title=\"Your first Coins\",Text=\"Coins are a bonus from gathering. Save them for upgrades and biome unlocks.\",Continue=true},\n {Title=\"The tree disappeared\",Text=\"Its reward has been collected and its interaction is disabled.\",Continue=true},\n {Title=\"Trees return\",Text=\"Trees respawn after 20 seconds, in exactly the same place.\",Continue=true},\n {Title=\"Trees give eggs\",Text=\"Every successful Meadow tree shake hatches a Meadow Egg automatically, for free.\",Continue=true},\n {Title=\"Hatch your first pet\",Text=\"Shake a real Meadow tree. Its egg immediately reveals a server-rolled pet.\",Target=\"Tree\"},\n {Title=\"Equip your pet\",Text=\"Open Pets and press Equip on your new companion.\"},\n {Title=\"Your companion follows\",Text=\"Your equipped pet follows you around the kingdom.\",Continue=true},\n {Title=\"Gather together\",Text=\"Shake another tree with your pet equipped for more resources and pet XP.\",Target=\"Tree\"},\n {Title=\"Explore the kingdom\",Text=\"Open Biomes to see the next unlock. Each biome has stronger pets and better gathering rewards.\",Continue=true},\n {Title=\"You're ready!\",Text=\"Complete challenges, collect Index rewards, and enjoy changing weather bonuses.\",Continue=true},\n}\n"}, {"path": ["ReplicatedStorage", "Shared", "Gameplay", "Definitions", "GameplayEffectsDefinitions"], "source": "-- Missing licensed/approved recordings stay silent. Insert actual owned SoundIds here.\nreturn {\n TreeRustle={SoundId=\"\",Volume=.22},\n TreeShake={SoundId=\"\",Volume=.18},\n EggWiggle={SoundId=\"\",Volume=.2},\n EggCrack={SoundId=\"\",Volume=.4},\n PetReveal={SoundId=\"\",Volume=.35},\n}\n"}, {"path": ["ReplicatedStorage", "Shared", "Gameplay", "Definitions", "AuthoredTreeDefinitions"], "source": "-- Confirmed asset identities from the authored place inspection on 2026-09-17.\n-- Deliberately excludes flower/bush/root/rock assets even when old metadata says Trees.\nreturn {\n [\"BirchTree_4\"] = true,\n [\"BirchTree_Dead_5\"] = true,\n [\"BirchTree_Dead_Snow_2\"] = true,\n [\"CactusFlowers_2\"] = true,\n [\"Cactus_1\"] = true,\n [\"Cactus_3\"] = true,\n [\"Cactus_4\"] = true,\n [\"Cactus_5\"] = true,\n [\"CommonTree_4\"] = true,\n [\"CommonTree_5\"] = true,\n [\"CommonTree_Dead_1\"] = true,\n [\"CommonTree_Dead_3\"] = true,\n [\"CommonTree_Dead_4\"] = true,\n [\"CommonTree_Dead_5\"] = true,\n [\"CommonTree_Snow_5\"] = true,\n [\"PalmTree_1\"] = true,\n [\"PalmTree_3\"] = true,\n [\"PineTree_3\"] = true,\n [\"PineTree_Snow_1\"] = true,\n [\"Tree3\"] = true,\n [\"Tree4\"] = true,\n [\"Tree_Bare_5\"] = true,\n [\"Tree_Cedar_1\"] = true,\n [\"Tree_Cedar_2\"] = true,\n [\"Tree_Cedar_3\"] = true,\n [\"Tree_Oak_1\"] = true,\n [\"Tree_Oak_2\"] = true,\n [\"Tree_Oak_3\"] = true,\n [\"Tree_Oak_4\"] = true,\n [\"Tree_Oak_5\"] = true,\n [\"Tree_Oak_6\"] = true,\n [\"Tree_Oak_7\"] = true,\n [\"Tree_Oak_8\"] = true,\n [\"Tree_Palm_1\"] = true,\n [\"Tree_Palm_2\"] = true,\n [\"Tree_Palm_3\"] = true,\n [\"Tree_Palm_5\"] = true,\n [\"Tree_Palm_6\"] = true,\n [\"Tree_Pine_1\"] = true,\n [\"Tree_Pine_2\"] = true,\n [\"Tree_Pine_3\"] = true,\n [\"Tree_Pine_5\"] = true,\n [\"Tree_Pine_6\"] = true,\n [\"TwistedTree_2\"] = true,\n [\"TwistedTree_4\"] = true,\n [\"TwistedTree_5\"] = true,\n [\"Willow_1\"] = true,\n [\"Willow_2\"] = true,\n [\"Willow_3\"] = true,\n [\"Willow_5\"] = true,\n [\"Willow_Autumn_4\"] = true,\n [\"Willow_Dead_4\"] = true,\n [\"Willow_Dead_5\"] = true,\n [\"Willow_Dead_Snow_3\"] = true,\n [\"Willow_Snow_5\"] = true,\n [\"cactus_short\"] = true,\n [\"cactus_tall\"] = true,\n [\"common_tree_1\"] = true,\n [\"common_tree_1_snow\"] = true,\n [\"common_tree_2\"] = true,\n [\"common_tree_3\"] = true,\n [\"common_tree_3_snow\"] = true,\n [\"common_tree_dead_1\"] = true,\n [\"common_tree_dead_2\"] = true,\n [\"common_tree_dead_3\"] = true,\n [\"palm_tree_1\"] = true,\n [\"palm_tree_2\"] = true,\n [\"palm_tree_3\"] = true,\n [\"pine_tree_1_snow\"] = true,\n [\"pine_tree_2_snow\"] = true,\n [\"pine_tree_3_snow\"] = true,\n [\"tree_cone\"] = true,\n [\"tree_fat\"] = true,\n [\"tree_oak\"] = true,\n [\"tree_palm\"] = true,\n [\"tree_palmBend\"] = true,\n [\"tree_palmDetailedShort\"] = true,\n [\"tree_palmDetailedTall\"] = true,\n [\"tree_palmShort\"] = true,\n [\"tree_palmTall\"] = true,\n [\"tree_pineRoundA\"] = true,\n [\"tree_thin\"] = true,\n}\n"}, {"path": ["ReplicatedStorage", "Shared", "Gameplay", "Definitions", "BiomeDefinitions"], "source": "local Legacy=require(script.Parent.Parent.Parent.Parent.SharedSource.Datas.AnimalKingdomConfig)\nlocal result={Ordered={}}\nfor order,biome in ipairs(Legacy.Biomes) do\n local def={Id=biome.Id,DisplayName=biome.DisplayName,Order=order,PreviousBiome=order>1 and Legacy.Biomes[order-1].Id or nil,\n  Cost=biome.UnlockCost,Currency=\"Coins\",EggId=biome.Id..\"Egg\",Egg=biome.Id..\"Egg\",ResourceTable=biome.Id..\"Tree\",\n  BaseReward=order==1 and 90 or math.max(180,math.floor(biome.UnlockCost/12))}\n result[def.Id]=def;table.insert(result.Ordered,def)\nend\nreturn result\n"}, {"path": ["StarterPlayer", "StarterPlayerScripts", "TreePresentation"], "source": "-- One bounded cosmetic listener; no gameplay reward or resource state is client-owned.\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal Players=game:GetService(\"Players\")\nlocal Tween=game:GetService(\"TweenService\")\nlocal Debris=game:GetService(\"Debris\")\nlocal Sounds=require(RS.Shared.Gameplay.PresentationSounds)\nlocal random=Random.new()\nlocal leafy={Meadow=true,Forest=true,Jungle=true,MagicalForest=true,Prehistoric=true}\nlocal connection=RS:WaitForChild(\"AnimalKingdomRemotes\"):WaitForChild(\"GatherVisual\").OnClientEvent:Connect(function(_,position,_,tree)\n local character=Players.LocalPlayer.Character;local root=character and character:FindFirstChild(\"HumanoidRootPart\")\n if not root or (root.Position-position).Magnitude>90 or not tree or not tree:IsDescendantOf(workspace) then return end\n local attachment=tree:FindFirstChild(\"AKTreeInteraction\",true)\n if attachment then Sounds.Play(\"TreeRustle\",attachment);Sounds.Play(\"TreeShake\",attachment) end\n if not leafy[tree:GetAttribute(\"BiomeId\")] then return end\n for _=1,5 do\n  local leaf=Instance.new(\"Part\");leaf.Name=\"TreeLeafEffect\";leaf.Size=Vector3.new(.55,.06,.3)\n  leaf.Color=Color3.fromRGB(106,161,80);leaf.Material=Enum.Material.SmoothPlastic\n  leaf.Anchored=true;leaf.CanCollide=false;leaf.CanTouch=false;leaf.CanQuery=false;leaf.CastShadow=false\n  leaf.CFrame=CFrame.new(position+Vector3.new(random:NextNumber(-2,2),3,random:NextNumber(-2,2)));leaf.Parent=workspace\n  Tween:Create(leaf,TweenInfo.new(1.2),{CFrame=leaf.CFrame*CFrame.new(random:NextNumber(-2,2),-3,random:NextNumber(-2,2))*CFrame.Angles(1,2,1),Transparency=1}):Play()\n  Debris:AddItem(leaf,1.3)\n end\nend)\nscript.Destroying:Connect(function() connection:Disconnect() end)\n"}]]====]);local mismatches={};for _,r in ipairs(rows) do local o=game;for _,name in ipairs(r.path) do o=o and o:FindFirstChild(name) end;if not o or o.Source~=r.source then table.insert(mismatches,table.concat(r.path,".")) end end;local temporary=0;for _,o in ipairs(game:GetDescendants()) do if o:GetAttribute("TemporaryAudit")==true then temporary+=1 end end;local generated=0;for _,o in ipairs(workspace:GetDescendants()) do if o:GetAttribute("GameplayGenerated")==true then generated+=1 end end;local missing={};for _,name in ipairs({"Pets","Eggs","Trees","Resources","Furniture","Decorations","Seasonal"}) do if not game.ReplicatedStorage:FindFirstChild("Assets") or not game.ReplicatedStorage.Assets:FindFirstChild(name) then table.insert(missing,name) end end;print("AK_TREE_FINAL_AUDIT "..game.HttpService:JSONEncode({SourceCount=#rows,SourceMismatches=mismatches,TemporaryAudits=temporary,GeneratedGeometry=generated,EggStations=#game.CollectionService:GetTagged("EggStation"),RegisteredTrees=#game.CollectionService:GetTagged("GatherableTree"),MissingAssetFolders=missing}))